// src/components/file-suggest/file-suggest.ts
var FileSuggest = class {
  constructor(options) {
    this.el = null;
    this.visible = false;
    this.files = [];
    this.selectedIndex = 0;
    this.app = options.app;
    this.onSelect = options.onSelect;
    this.maxResults = options.maxResults || 10;
    this.el = this.createDropdown();
  }
  /**
   * 创建下拉菜单容器
   */
  createDropdown() {
    const dropdown = document.createElement("div");
    dropdown.className = "deeppdf-file-suggest";
    dropdown.style.display = "none";
    document.body.appendChild(dropdown);
    return dropdown;
  }
  /**
   * 搜索并显示结果
   */
  search(query) {
    this.files = this.searchFiles(query);
    this.selectedIndex = 0;
    this.renderResults();
    if (this.files.length > 0) {
      this.show();
    } else {
      this.hide();
    }
  }
  /**
   * 搜索文件
   */
  searchFiles(query) {
    const allFiles = this.app.vault.getMarkdownFiles();
    const queryLower = query.toLowerCase().trim();
    if (!queryLower) {
      return allFiles.sort((a, b) => b.stat.mtime - a.stat.mtime).slice(0, this.maxResults);
    }
    return allFiles.filter((file) => {
      const basenameLower = file.basename.toLowerCase();
      const pathLower = file.path.toLowerCase();
      return basenameLower.includes(queryLower) || pathLower.includes(queryLower);
    }).sort((a, b) => {
      const aStartsWith = a.basename.toLowerCase().startsWith(queryLower);
      const bStartsWith = b.basename.toLowerCase().startsWith(queryLower);
      if (aStartsWith && !bStartsWith)
        return -1;
      if (!aStartsWith && bStartsWith)
        return 1;
      return b.stat.mtime - a.stat.mtime;
    }).slice(0, this.maxResults);
  }
  /**
   * 渲染搜索结果
   */
  renderResults() {
    if (!this.el)
      return;
    this.el.innerHTML = "";
    if (this.files.length === 0) {
      this.el.innerHTML = '<div class="deeppdf-file-suggest-empty">\u6CA1\u6709\u627E\u5230\u5339\u914D\u7684\u6587\u4EF6</div>';
      return;
    }
    this.files.forEach((file, index) => {
      var _a;
      const item = document.createElement("div");
      item.className = "deeppdf-file-suggest-item";
      if (index === this.selectedIndex) {
        item.classList.add("selected");
      }
      item.innerHTML = `
				<span class="deeppdf-file-suggest-icon">\u{1F4C4}</span>
				<span class="deeppdf-file-suggest-name">${this.escapeHtml(file.basename)}</span>
				<span class="deeppdf-file-suggest-path">${this.escapeHtml(((_a = file.parent) == null ? void 0 : _a.path) || "/")}</span>
			`;
      item.addEventListener("click", () => {
        this.selectFile(index);
      });
      item.addEventListener("mouseenter", () => {
        this.selectedIndex = index;
        this.updateSelection();
      });
      this.el.appendChild(item);
    });
  }
  /**
   * 更新选中状态
   */
  updateSelection() {
    if (!this.el)
      return;
    const items = this.el.querySelectorAll(".deeppdf-file-suggest-item");
    items.forEach((item, index) => {
      if (index === this.selectedIndex) {
        item.classList.add("selected");
      } else {
        item.classList.remove("selected");
      }
    });
  }
  /**
   * 选择文件
   */
  selectFile(index) {
    if (index >= 0 && index < this.files.length) {
      this.onSelect(this.files[index]);
      this.hide();
    }
  }
  /**
   * 选择当前选中的文件
   */
  selectCurrent() {
    if (this.visible && this.files.length > 0) {
      this.selectFile(this.selectedIndex);
    }
  }
  /**
   * 键盘导航
   * @returns 是否处理了该事件
   */
  handleKeydown(event) {
    if (!this.visible)
      return false;
    switch (event.key) {
      case "ArrowDown":
        event.preventDefault();
        this.selectedIndex = Math.min(this.selectedIndex + 1, this.files.length - 1);
        this.updateSelection();
        this.scrollToSelected();
        return true;
      case "ArrowUp":
        event.preventDefault();
        this.selectedIndex = Math.max(this.selectedIndex - 1, 0);
        this.updateSelection();
        this.scrollToSelected();
        return true;
      case "Enter":
      case "Tab":
        event.preventDefault();
        this.selectFile(this.selectedIndex);
        return true;
      case "Escape":
        this.hide();
        return true;
      default:
        return false;
    }
  }
  /**
   * 滚动到选中项
   */
  scrollToSelected() {
    if (!this.el)
      return;
    const selectedItem = this.el.querySelector(".deeppdf-file-suggest-item.selected");
    if (selectedItem) {
      selectedItem.scrollIntoView({ block: "nearest" });
    }
  }
  /**
   * 显示下拉菜单
   */
  show() {
    if (this.el && this.files.length > 0) {
      this.el.style.display = "block";
      this.visible = true;
    }
  }
  /**
   * 隐藏下拉菜单
   */
  hide() {
    if (this.el) {
      this.el.style.display = "none";
      this.visible = false;
    }
  }
  /**
   * 定位下拉菜单
   */
  setPosition(x, y) {
    if (this.el) {
      const rect = this.el.getBoundingClientRect();
      const viewportWidth = window.innerWidth;
      const viewportHeight = window.innerHeight;
      let posX = x;
      let posY = y;
      if (x + 300 > viewportWidth) {
        posX = viewportWidth - 310;
      }
      if (y + 300 > viewportHeight) {
        posY = y - 10;
        this.el.style.transformOrigin = "bottom left";
      } else {
        this.el.style.transformOrigin = "top left";
      }
      this.el.style.left = `${Math.max(10, posX)}px`;
      this.el.style.top = `${Math.max(10, posY)}px`;
    }
  }
  /**
   * 是否可见
   */
  isVisible() {
    return this.visible;
  }
  /**
   * HTML 转义
   */
  escapeHtml(text) {
    const div = document.createElement("div");
    div.textContent = text;
    return div.innerHTML;
  }
  /**
   * 销毁组件
   */
  destroy() {
    if (this.el && this.el.parentNode) {
      this.el.parentNode.removeChild(this.el);
    }
    this.el = null;
    this.files = [];
  }
};

