// src/agent/utils/link-validator.ts
init_logger();
function extractChapterIndexFromFilename(filename) {
  const match = filename.match(/^(\d+)-/);
  if (match) {
    return parseInt(match[1], 10);
  }
  return null;
}
function parseWikiLink(linkText) {
  const match = linkText.match(/\[\[([^\]|]+)(?:\|([^\]]+))?\]\]/);
  if (!match) {
    return null;
  }
  const fullPath = match[1].trim();
  const displayText = (match[2] || fullPath.split("/").pop() || "").trim();
  const parts = fullPath.split("/");
  const filename = parts.pop() || "";
  const folder = parts.join("/");
  return {
    fullPath,
    displayText,
    folder,
    filename
  };
}
async function fuzzyMatchFile(app, folder, targetFilename) {
  const folderPath = `DeepReader/${folder}`;
  try {
    const folderExists = await app.vault.adapter.exists(folderPath);
    if (!folderExists) {
      toolsLog("[LinkValidator] \u6587\u4EF6\u5939\u4E0D\u5B58\u5728:", folderPath);
      return null;
    }
    const files = await app.vault.adapter.list(folderPath);
    const mdFiles = files.files.filter((f) => f.endsWith(".md"));
    const exactMatch = mdFiles.find((f) => f.endsWith(`/${targetFilename}`));
    if (exactMatch) {
      return exactMatch;
    }
    const targetTitle = targetFilename.replace(".md", "").replace(/^\d+-/, "").trim();
    if (!targetTitle) {
      return null;
    }
    let bestMatch = null;
    let bestScore = 0;
    for (const file of mdFiles) {
      const filename = file.split("/").pop() || "";
      const fileTitle = filename.replace(".md", "").replace(/^\d+-/, "").trim();
      const score = calculateSimilarity(targetTitle, fileTitle);
      if (score > bestScore && score > 0.5) {
        bestScore = score;
        bestMatch = file;
      }
    }
    if (bestMatch) {
      toolsLog("[LinkValidator] \u6A21\u7CCA\u5339\u914D\u6210\u529F:", targetFilename, "->", bestMatch, "\u5206\u6570:", bestScore);
    }
    return bestMatch;
  } catch (err) {
    error("[LinkValidator] \u6A21\u7CCA\u5339\u914D\u5931\u8D25:", err);
    return null;
  }
}
function calculateSimilarity(str1, str2) {
  if (str1 === str2)
    return 1;
  const len1 = str1.length;
  const len2 = str2.length;
  const maxLen = Math.max(len1, len2);
  if (maxLen === 0)
    return 1;
  const s1 = str1.toLowerCase();
  const s2 = str2.toLowerCase();
  if (s1.includes(s2) || s2.includes(s1)) {
    return Math.min(len1, len2) / maxLen;
  }
  let commonChars = 0;
  const s2Chars = new Set(s2);
  for (const char of s1) {
    if (s2Chars.has(char)) {
      commonChars++;
    }
  }
  return commonChars / maxLen;
}
async function validateAndCorrectLinks(app, content) {
  const wikiLinkRegex = /\[\[([^\]|]+)(?:\|([^\]]+))?\]\]/g;
  const validatedLinks = [];
  let correctedContent = content;
  const corrections = [];
  const matches = Array.from(content.matchAll(wikiLinkRegex));
  for (const match of matches) {
    const fullMatch = match[0];
    const parsed = parseWikiLink(fullMatch);
    if (!parsed)
      continue;
    const { folder, filename, fullPath, displayText } = parsed;
    const fullPathInVault = `DeepReader/${fullPath}`;
    const exists = await app.vault.adapter.exists(fullPathInVault);
    if (exists) {
      const chapterIndex = extractChapterIndexFromFilename(filename);
      validatedLinks.push({
        original: fullMatch,
        corrected: fullMatch,
        isCorrected: false,
        existsPath: fullPathInVault,
        chapterIndex
      });
    } else {
      const matchedPath = await fuzzyMatchFile(app, folder, filename);
      if (matchedPath) {
        const correctedFilename = matchedPath.split("/").pop() || filename;
        const correctedFullPath = `${folder}/${correctedFilename}`;
        const correctedLink = `[[${correctedFullPath}|${displayText}]]`;
        corrections.push({
          original: fullMatch,
          corrected: correctedLink
        });
        const chapterIndex = extractChapterIndexFromFilename(correctedFilename);
        validatedLinks.push({
          original: fullMatch,
          corrected: correctedLink,
          isCorrected: true,
          existsPath: matchedPath,
          chapterIndex
        });
        toolsLog("[LinkValidator] \u94FE\u63A5\u7EA0\u6B63:", fullPath, "->", correctedFullPath);
      } else {
        validatedLinks.push({
          original: fullMatch,
          corrected: fullMatch,
          isCorrected: false,
          existsPath: null,
          chapterIndex: null
        });
        toolsLog("[LinkValidator] \u65E0\u6CD5\u627E\u5230\u5339\u914D:", fullPath);
      }
    }
  }
  for (const { original, corrected } of corrections) {
    correctedContent = correctedContent.replace(original, corrected);
  }
  return { correctedContent, validatedLinks };
}

