// src/agent/cognitive-engine/interceptor/scope-interceptor.ts
function createScopeInterceptor(scopeNodeIds) {
  const hasScope = scopeNodeIds.length > 0;
  return (toolName, toolArgs) => {
    if (toolName === "search_markdown_text") {
      if (hasScope) {
        return {
          ...toolArgs,
          scope_node_ids: scopeNodeIds
          // snake_case to match tool parameter
        };
      }
      return toolArgs;
    }
    return toolArgs;
  };
}

